// Genera una petición independiente por indicador.
const token = env.get('ESIOS_TOKEN');
if (!token) {
    node.status({fill:'red', shape:'ring', text:'Falta ESIOS_TOKEN'});
    node.error('ESIOS_TOKEN no está definido');
    return null;
}
const indicators = [
    ['2037','demanda_real'], ['2038','eolica'], ['2044','solar_fv'],
    ['2045','solar_termica'], ['2039','nuclear'], ['2040','carbon'],
    ['2041','ciclo_combinado'], ['2042','hidraulica'],
    ['2051','cogeneracion_residuos'], ['2046','termica_renovable'],
    ['2043','intercambios'], ['2065','consumo_bombeo'],
    ['2066','turbinacion_bombeo'], ['2199','baterias_carga'],
    ['2198','baterias_entrega']
];
const end = new Date();
const start = new Date(end.getTime() - 30 * 60 * 1000);
node.status({fill:'blue', shape:'dot', text:`${indicators.length} indicadores`});
return [indicators.map(([id, tecnologia]) => ({
    url: `https://api.esios.ree.es/indicators/${id}?start_date=${encodeURIComponent(start.toISOString())}&end_date=${encodeURIComponent(end.toISOString())}`,
    headers: {
        'x-api-key': token,
        'Accept': 'application/json, application/vnd.esios-api-v1+json'
    },
    tecnologia,
    indicatorId: id
}))];

// Convierte la respuesta de ESIOS y registra cuándo llegó a Node-RED.
const indicator = msg.payload?.indicator;
const values = indicator?.values;
if (!Array.isArray(values)) {
    node.error(`${msg.tecnologia}: la respuesta de ESIOS no contiene indicator.values`);
    return null;
}
const points = [];
let latestDataTimestamp = 0;
for (const item of values) {
    const mw = Number(item.value);
    const timestamp = Date.parse(item.datetime_utc || item.datetime);
    if (!Number.isFinite(mw) || !Number.isFinite(timestamp)) {
        node.warn(`${msg.tecnologia}: dato inválido`);
        continue;
    }
    latestDataTimestamp = Math.max(latestDataTimestamp, timestamp);
    points.push({
        measurement: 'generacion',
        tags: {
            tecnologia: String(msg.tecnologia),
            geo: String(item.geo_name || 'nacional')
        },
        fields: { mw },
        timestamp: new Date(timestamp)
    });
}
const pollTimestamp = Date.now();
points.push(...points.filter((point) => point.measurement === 'generacion').map((point) => ({...point, measurement: 'generacion_ingestion', fields: {...point.fields, source_timestamp_ms: point.timestamp.getTime()}, timestamp: new Date(pollTimestamp)})));
const apiUpdatedTimestamp = Date.parse(indicator.values_updated_at);
points.push({
    measurement: 'esios_ingestion',
    tags: { tecnologia: String(msg.tecnologia) },
    fields: {
        poll_ok: 1,
        values_count: values.length,
        latest_data_timestamp_ms: latestDataTimestamp,
        api_updated_timestamp_ms: Number.isFinite(apiUpdatedTimestamp) ? apiUpdatedTimestamp : 0
    },
    timestamp: new Date(pollTimestamp)
});
msg.payload = points;
node.status({fill:'green', shape:'dot', text:`${msg.tecnologia}: ${values.length} recibidos`});
if (values.length === 0) node.warn(`${msg.tecnologia} devolvió values vacío`);
return msg;

// Influx identifica un punto por medicion + tags + timestamp.
// Añadimos una clave de muestra a la copia de auditoria para que dos
// muestras recibidas en el mismo milisegundo no se sobrescriban.
const points = Array.isArray(msg.payload) ? msg.payload : [];
let invalid = 0;
for (const [index, point] of points.entries()) {
    const value = Number(point.fields?.mw);
    if (point.measurement === 'generacion' && (!Number.isFinite(value) || value < 0)) {
        invalid++;
        point.fields = {...point.fields, quality_flag: 'fuera_de_rango'};
        continue;
    }
    if (point.measurement === 'generacion_ingestion') {
        const source = point.fields?.source_timestamp_ms || point.fields?.poll_timestamp_ms || index;
        point.tags = {...point.tags, muestra: `${msg.tecnologia}|${point.tags?.geo || 'nacional'}|${source}|${index}`};
    }
}
msg.payload = points.filter((point) => point.measurement !== 'generacion' || Number.isFinite(Number(point.fields?.mw)));
if (invalid) node.warn(`${msg.tecnologia}: ${invalid} muestras descartadas por calidad`);
return msg;

// Hace visible el error sin volver a enviarlo al nodo catch.
const error = msg.error?.message || 'Error desconocido';
node.status({fill:'red', shape:'ring', text:error.slice(0, 80)});
node.warn(error);
return msg;
